-- Replace every raid tier token drop with the tier pieces that token buys, so each class gets real gear
-- (and mod-nightmare can swap it for its Legendary/Nightmare twin; it never swaps tokens).
-- Token -> piece map: vendor exchanges (ItemExtendedCost.dbc) and token turn-in quests, tier set pieces only.
-- 1. Restore stock token rows that were deleted without a replacement (T7, T8, T9 only; T3-T6/T10 are already
--    converted) into loot tables that are still in use and don't already hold that token's pieces.
-- 2. Expand every token row: grouped rows become the pieces in the same group (explicit chance split evenly);
--    ungrouped rows point at a new reference 1900000 + token holding the pieces in one equal-chance group.

DROP TEMPORARY TABLE IF EXISTS `tmp_tier_map`;
CREATE TEMPORARY TABLE `tmp_tier_map` (`token` INT UNSIGNED, `piece` INT UNSIGNED, PRIMARY KEY (`token`, `piece`)) ENGINE = InnoDB;
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_tok`;
CREATE TEMPORARY TABLE `tmp_tier_tok` ENGINE = InnoDB AS SELECT `token`, COUNT(*) AS `n` FROM `tmp_tier_map` GROUP BY `token`;

DROP TEMPORARY TABLE IF EXISTS `tmp_tier_stock`;
CREATE TEMPORARY TABLE `tmp_tier_stock` (`tbl` VARCHAR(10), `Entry` INT UNSIGNED, `Item` INT UNSIGNED, `Chance` FLOAT, `QuestRequired` TINYINT, `LootMode` SMALLINT, `GroupId` TINYINT, `MinCount` TINYINT, `MaxCount` TINYINT) ENGINE = InnoDB;

-- creature_loot_template
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_restore`;
CREATE TEMPORARY TABLE `tmp_tier_restore` ENGINE = InnoDB AS SELECT s.* FROM `tmp_tier_stock` s
WHERE s.`tbl` = 'creature' AND s.`Entry` IN (SELECT `Entry` FROM `creature_loot_template`)
  AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` l WHERE l.`Entry` = s.`Entry` AND l.`Item` = s.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` l JOIN `tmp_tier_map` m ON m.`piece` = l.`Item` WHERE l.`Entry` = s.`Entry` AND m.`token` = s.`Item`);
DELETE FROM `creature_loot_template` WHERE (`Entry`, `Item`) IN (SELECT `Entry`, `Item` FROM `tmp_tier_restore`);
SELECT `Entry`, `Item`, 0, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, 'tier token (restored)' FROM `tmp_tier_restore`;
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_rows`;
CREATE TEMPORARY TABLE `tmp_tier_rows` ENGINE = InnoDB AS SELECT l.* FROM `creature_loot_template` l JOIN `tmp_tier_tok` k ON k.`token` = l.`Item` WHERE l.`Reference` = 0;
-- grouped token rows -> pieces in the same group
DELETE FROM `creature_loot_template` WHERE (`Entry`, `Item`) IN (SELECT m.`Entry`, mp.`piece` FROM `tmp_tier_rows` m JOIN `tmp_tier_map` mp ON mp.`token` = m.`Item` WHERE m.`GroupId` > 0);
SELECT r.`Entry`, mp.`piece`, 0, IF(r.`Chance` = 0, 0, r.`Chance` / k.`n`), 0, r.`LootMode`, r.`GroupId`, r.`MinCount`, r.`MaxCount`, LEFT(i.`name`, 255)
FROM `tmp_tier_rows` r JOIN `tmp_tier_tok` k ON k.`token` = r.`Item` JOIN `tmp_tier_map` mp ON mp.`token` = r.`Item` JOIN `item_template` i ON i.`entry` = mp.`piece`
WHERE r.`GroupId` > 0;
DELETE FROM `creature_loot_template` WHERE (`Entry`, `Item`) IN (SELECT `Entry`, `Item` FROM `tmp_tier_rows` WHERE `GroupId` > 0);
-- ungrouped token rows -> reference to the token's pieces
UPDATE `creature_loot_template` l JOIN `tmp_tier_rows` r ON r.`Entry` = l.`Entry` AND r.`Item` = l.`Item` AND r.`GroupId` = 0
SET l.`Reference` = 1900000 + l.`Item`, l.`Comment` = CONCAT('tier pieces for token ', l.`Item`);

-- reference_loot_template
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_restore`;
CREATE TEMPORARY TABLE `tmp_tier_restore` ENGINE = InnoDB AS SELECT s.* FROM `tmp_tier_stock` s
WHERE s.`tbl` = 'reference' AND s.`Entry` IN (SELECT `Entry` FROM `reference_loot_template`)
  AND NOT EXISTS (SELECT 1 FROM `reference_loot_template` l WHERE l.`Entry` = s.`Entry` AND l.`Item` = s.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `reference_loot_template` l JOIN `tmp_tier_map` m ON m.`piece` = l.`Item` WHERE l.`Entry` = s.`Entry` AND m.`token` = s.`Item`);
DELETE FROM `reference_loot_template` WHERE (`Entry`, `Item`) IN (SELECT `Entry`, `Item` FROM `tmp_tier_restore`);
SELECT `Entry`, `Item`, 0, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, 'tier token (restored)' FROM `tmp_tier_restore`;
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_rows`;
CREATE TEMPORARY TABLE `tmp_tier_rows` ENGINE = InnoDB AS SELECT l.* FROM `reference_loot_template` l JOIN `tmp_tier_tok` k ON k.`token` = l.`Item` WHERE l.`Reference` = 0;
-- grouped token rows -> pieces in the same group
DELETE FROM `reference_loot_template` WHERE (`Entry`, `Item`) IN (SELECT m.`Entry`, mp.`piece` FROM `tmp_tier_rows` m JOIN `tmp_tier_map` mp ON mp.`token` = m.`Item` WHERE m.`GroupId` > 0);
SELECT r.`Entry`, mp.`piece`, 0, IF(r.`Chance` = 0, 0, r.`Chance` / k.`n`), 0, r.`LootMode`, r.`GroupId`, r.`MinCount`, r.`MaxCount`, LEFT(i.`name`, 255)
FROM `tmp_tier_rows` r JOIN `tmp_tier_tok` k ON k.`token` = r.`Item` JOIN `tmp_tier_map` mp ON mp.`token` = r.`Item` JOIN `item_template` i ON i.`entry` = mp.`piece`
WHERE r.`GroupId` > 0;
DELETE FROM `reference_loot_template` WHERE (`Entry`, `Item`) IN (SELECT `Entry`, `Item` FROM `tmp_tier_rows` WHERE `GroupId` > 0);
-- ungrouped token rows -> reference to the token's pieces
UPDATE `reference_loot_template` l JOIN `tmp_tier_rows` r ON r.`Entry` = l.`Entry` AND r.`Item` = l.`Item` AND r.`GroupId` = 0
SET l.`Reference` = 1900000 + l.`Item`, l.`Comment` = CONCAT('tier pieces for token ', l.`Item`);

-- gameobject_loot_template
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_restore`;
CREATE TEMPORARY TABLE `tmp_tier_restore` ENGINE = InnoDB AS SELECT s.* FROM `tmp_tier_stock` s
WHERE s.`tbl` = 'gameobject' AND s.`Entry` IN (SELECT `Entry` FROM `gameobject_loot_template`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject_loot_template` l WHERE l.`Entry` = s.`Entry` AND l.`Item` = s.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject_loot_template` l JOIN `tmp_tier_map` m ON m.`piece` = l.`Item` WHERE l.`Entry` = s.`Entry` AND m.`token` = s.`Item`);
DELETE FROM `gameobject_loot_template` WHERE (`Entry`, `Item`) IN (SELECT `Entry`, `Item` FROM `tmp_tier_restore`);
SELECT `Entry`, `Item`, 0, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, 'tier token (restored)' FROM `tmp_tier_restore`;
DROP TEMPORARY TABLE IF EXISTS `tmp_tier_rows`;
CREATE TEMPORARY TABLE `tmp_tier_rows` ENGINE = InnoDB AS SELECT l.* FROM `gameobject_loot_template` l JOIN `tmp_tier_tok` k ON k.`token` = l.`Item` WHERE l.`Reference` = 0;
-- grouped token rows -> pieces in the same group
DELETE FROM `gameobject_loot_template` WHERE (`Entry`, `Item`) IN (SELECT m.`Entry`, mp.`piece` FROM `tmp_tier_rows` m JOIN `tmp_tier_map` mp ON mp.`token` = m.`Item` WHERE m.`GroupId` > 0);
SELECT r.`Entry`, mp.`piece`, 0, IF(r.`Chance` = 0, 0, r.`Chance` / k.`n`), 0, r.`LootMode`, r.`GroupId`, r.`MinCount`, r.`MaxCount`, LEFT(i.`name`, 255)
FROM `tmp_tier_rows` r JOIN `tmp_tier_tok` k ON k.`token` = r.`Item` JOIN `tmp_tier_map` mp ON mp.`token` = r.`Item` JOIN `item_template` i ON i.`entry` = mp.`piece`
WHERE r.`GroupId` > 0;
DELETE FROM `gameobject_loot_template` WHERE (`Entry`, `Item`) IN (SELECT `Entry`, `Item` FROM `tmp_tier_rows` WHERE `GroupId` > 0);
-- ungrouped token rows -> reference to the token's pieces
UPDATE `gameobject_loot_template` l JOIN `tmp_tier_rows` r ON r.`Entry` = l.`Entry` AND r.`Item` = l.`Item` AND r.`GroupId` = 0
SET l.`Reference` = 1900000 + l.`Item`, l.`Comment` = CONCAT('tier pieces for token ', l.`Item`);

-- per-token piece references used by the ungrouped rows above
DELETE FROM `reference_loot_template` WHERE `Entry` BETWEEN 1900001 AND 1999999 AND `Entry` - 1900000 IN (SELECT `token` FROM `tmp_tier_tok`);
SELECT 1900000 + mp.`token`, mp.`piece`, 0, 0, 0, 1, 1, 1, 1, LEFT(i.`name`, 255)
FROM `tmp_tier_map` mp JOIN `item_template` i ON i.`entry` = mp.`piece`;

DROP TEMPORARY TABLE IF EXISTS `tmp_tier_map`, `tmp_tier_tok`, `tmp_tier_stock`, `tmp_tier_restore`, `tmp_tier_rows`;
